/**
 * Real Bill Layne Insurance brand assets, embedded as data URIs so they render
 * reliably in the design app and in exports — no hotlink / CSP dependency.
 * Sources: agency logo i.imgur.com/lxu9nfT.png (optimized 640px, 64-color);
 * agency QR i.imgur.com/drzOEXc.png (encodes cards.billlayneinsurance.com/agency-contact);
 * carrier logos from the agency's set + NC Grange from ncgm.com/images/logomain.png.
 * Update here if the brand assets change.
 */

export const BLI_LOGO = "data:image/png;base64,";

export const BLI_QR = "data:image/png;base64,";

/** Known carrier logos (real files), keyed by normalized name. */
export const CARRIER_LOGOS: Record<string, string> = {
  nationwide: "data:image/png;base64,",
  progressive: "data:image/png;base64,",
  travelers: "data:image/png;base64,",
  nationalgeneral: "data:image/png;base64,",
  alamance: "data:image/png;base64,",
  foremost: "data:image/jpeg;base64,",
  ncgrange: "data:image/png;base64,",
  ncgrangemutual: "data:image/png;base64,",
  grange: "data:image/png;base64,",
};

/** Human-facing carrier names Bill can request by. */
export const CARRIER_NAMES = ['Nationwide', 'Progressive', 'Travelers', 'National General', 'NC Grange', 'Alamance', 'Foremost'] as const;

const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]/g, '');

/** Resolve a carrier name (any casing / spacing) to its real logo data URI. */
export function carrierLogo(name?: string): string | undefined {
  if (!name) return undefined;
  return CARRIER_LOGOS[norm(name)];
}
